      where: { id: subscription.id, organizationId: params.organizationId },
      data: {
        stripeStatus: updated.status,
        cancelAtPeriodEnd: updated.cancel_at_period_end,
        canceledAt: updated.canceled_at
          ? new Date(updated.canceled_at * 1000)
          : null,
      },
    });
    await writeBillingAudit({
      organizationId: params.organizationId,
      eventType: 'admin_subscription_canceled',
      skuKey: subscription.skuKey,
      metadata: {
        adminUserId: params.adminUserId,
        subscriptionId: subscription.id,
        mode: params.mode,
        note: params.note,
      },
    });
    return this.adminBilling.getStatus(params.organizationId);
  }

  async resumeSubscription(params: {
    organizationId: string;
    adminUserId: string;
    subscriptionId: string;
    note: string;
  }): Promise<AdminBillingStatus> {
    assertStripeBillingConfigured(this.stripeService);
    const subscription = await this.getScopedSubscription(params);
    const updated = await this.stripeService
      .getClient()
      .subscriptions.update(subscription.stripeSubscriptionId, {
        cancel_at_period_end: false,
      });
    await db.organizationBillingSubscription.updateMany({
      where: { id: subscription.id, organizationId: params.organizationId },
      data: {
        stripeStatus: updated.status,
        cancelAtPeriodEnd: updated.cancel_at_period_end,
        canceledAt: null,
      },
    });
    await writeBillingAudit({
      organizationId: params.organizationId,
      eventType: 'admin_subscription_resumed',
      skuKey: subscription.skuKey,
      metadata: {
        adminUserId: params.adminUserId,
        subscriptionId: subscription.id,
        note: params.note,
      },
    });
    return this.adminBilling.getStatus(params.organizationId);
  }

  async createPaymentLink(params: {
    organizationId: string;
    successUrl: string;
    cancelUrl: string;
  }) {
    validateBillingRedirectUrl(params.successUrl);
    validateBillingRedirectUrl(params.cancelUrl);
    return this.billingService.createSetupSession(params);
  }

  async grantCredits(params: {
    organizationId: string;
    adminUserId: string;
    productKey: 'pentest' | 'background_check';
    quantity: number;
    note: string;
    confirm?: string;
  }): Promise<AdminBillingStatus> {
    if (params.quantity >= 25 && params.confirm !== 'grant credits') {
      throw new BadRequestException('Type "grant credits" to confirm.');
    }
    await this.credits.grant({
      organizationId: params.organizationId,
      productKey: params.productKey,
      quantity: params.quantity,
      source: 'manual',
      note: params.note,
      adminUserId: params.adminUserId,
    });
    await writeBillingAudit({
      organizationId: params.organizationId,
      eventType: 'admin_credits_granted',
      metadata: {
        adminUserId: params.adminUserId,
        productKey: params.productKey,
        quantity: params.quantity,
        note: params.note,
      },
    });
    return this.adminBilling.getStatus(params.organizationId);
  }

  async getInvoiceRetryLink(params: {
    organizationId: string;
    adminUserId: string;
    invoiceId: string;
    note: string;
  }) {
    assertStripeBillingConfigured(this.stripeService);
    const { billing } = await getOrgBillingContext(params.organizationId);
    if (!billing) throw new NotFoundException('Billing customer not found.');
    const invoice = await this.stripeService
      .getClient()
      .invoices.retrieve(params.invoiceId);
    if (getInvoiceCustomerId(invoice) !== billing.stripeCustomerId) {
      throw new NotFoundException('Invoice not found.');
    }
    await writeBillingAudit({
      organizationId: params.organizationId,
      eventType: 'admin_invoice_retry_link_created',
      metadata: {
        adminUserId: params.adminUserId,
        invoiceId: params.invoiceId,
        note: params.note,
      },
    });
    return {
      hostedInvoiceUrl: invoice.hosted_invoice_url ?? null,
      invoicePdfUrl: invoice.invoice_pdf ?? null,
      status: invoice.status ?? 'unknown',
    };
  }

  private async getScopedSubscription(params: {
    organizationId: string;
    subscriptionId: string;
  }) {
    const subscription = await db.organizationBillingSubscription.findFirst({
      where: {
        id: params.subscriptionId,
        organizationId: params.organizationId,
      },
    });
    if (!subscription) throw new NotFoundException('Subscription not found.');
    return subscription;
  }
}

import { db } from '@db';
import { IsmsService } from './isms.service';
import type { IsmsVersionService } from './isms-version.service';

jest.mock('@db', () => ({
  db: {
    frameworkEditorFramework: { findUnique: jest.fn() },
    frameworkEditorIsmsDocumentTemplate: { findMany: jest.fn() },
    ismsDocument: {
      findMany: jest.fn(),
      createMany: jest.fn(),
    },
    control: { findMany: jest.fn() },
    ismsDocumentControlLink: { createMany: jest.fn() },
  },
}));
jest.mock('./documents/data-source', () => ({
  collectPlatformData: jest.fn(),
}));
jest.mock('./documents/generate', () => ({
  runDerivation: jest.fn(),
}));

const mockDb = jest.mocked(db);

// ensureSetup never touches the version service; a bare stub satisfies the ctor.
const versionService = {} as unknown as IsmsVersionService;

/** Convenience accessor for the first createMany call's `data` array. */
const createManyData = () =>
  (mockDb.ismsDocument.createMany as jest.Mock).mock.calls[0][0].data;

describe('IsmsService ensureSetup fallback to ISMS_TYPE_DEFINITIONS (no templates seeded)', () => {
  let service: IsmsService;
  const dto = { organizationId: 'org_1', frameworkId: 'fw_1', canWrite: true };
  const mockTemplates = mockDb.frameworkEditorIsmsDocumentTemplate
    .findMany as jest.Mock;

  beforeEach(() => {
    jest.clearAllMocks();
    service = new IsmsService(versionService);
    (mockDb.control.findMany as jest.Mock).mockResolvedValue([]);
    (mockDb.ismsDocument.createMany as jest.Mock).mockResolvedValue({
      count: 0,
    });
    (mockDb.ismsDocumentControlLink.createMany as jest.Mock).mockResolvedValue({
      count: 0,
    });
    mockTemplates.mockResolvedValue([]);
  });

  it('creates only missing document types and maps requirements', async () => {
    (
      mockDb.frameworkEditorFramework.findUnique as jest.Mock
    ).mockResolvedValue({
      id: 'fw_1',
      requirements: [{ id: 'req_41', name: '4.1 Context', identifier: '4.1' }],
    });
    // One existing type so only the other five are created.
    (mockDb.ismsDocument.findMany as jest.Mock)
      .mockResolvedValueOnce([{ type: 'context_of_organization' }]) // existing-types probe
      .mockResolvedValueOnce([]) // created lookup
      .mockResolvedValueOnce([
        {
          id: 'doc_1',
          type: 'context_of_organization',
          status: 'draft',
          requirementId: 'req_41',
        },
      ]); // final list

    const result = await service.ensureSetup(dto);

    expect(mockDb.ismsDocument.createMany).toHaveBeenCalledTimes(1);
    expect(createManyData()).toHaveLength(5);
    // Definition-derived docs carry no templateId.
    expect(createManyData()[0].templateId).toBeNull();
    expect(result.success).toBe(true);
    expect(result.documents[0]).toEqual({
      id: 'doc_1',
      type: 'context_of_organization',
      status: 'draft',
      requirementId: 'req_41',
      hasApprovedVersion: false,
    });
  });

  it('leaves requirementId null when no clause matches', async () => {
    (
      mockDb.frameworkEditorFramework.findUnique as jest.Mock
    ).mockResolvedValue({ id: 'fw_1', requirements: [] });
    (mockDb.ismsDocument.findMany as jest.Mock)
      .mockResolvedValueOnce([])
      .mockResolvedValueOnce([])
      .mockResolvedValueOnce([]);

    await service.ensureSetup(dto);

    expect(createManyData()).toHaveLength(6);
    expect(createManyData()[0].requirementId).toBeNull();
  });
});

